<?php
function showcase_defaults():array{return ['count'=>4,'sections'=>['new'=>true,'hot'=>true,'best'=>true,'picks'=>true,'offers'=>true,'categories'=>true,'budget'=>true,'recent'=>true]];}
function showcase_config():array{$v=json_decode(setting('showcase_settings','{}'),true)?:[];$d=showcase_defaults();return ['count'=>in_array((int)($v['count']??4),[4,8])?(int)($v['count']??4):4,'sections'=>array_replace($d['sections'],$v['sections']??[])];}
function product_thumbnail(string $url):string{global $root;$thumb=str_replace('-product.webp','-thumb.webp',$url);return $thumb!==$url&&is_file($root.'/public'.$thumb)?$thumb:$url;}
/** Decode/re-encode to remove metadata and use fixed, safe raster outputs. */
function optimize_image(string $path,string $purpose='media',?string $key=null):array{global $root;if(!extension_loaded('gd')||!function_exists('imagewebp'))throw new RuntimeException('Image processing requires PHP GD with WebP support.');$info=@getimagesize($path);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);if(!$info||!in_array($mime,['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('Choose a valid JPEG, PNG or WebP image.');[$w,$h]=$info;if($w<1||$h<1||$w>10000||$h>10000||$w*$h>16000000)throw new RuntimeException('Choose an image up to 16 megapixels and 10,000 pixels per side.');$limit=ini_get('memory_limit');if($limit!=='-1'){$unit=strtolower(substr($limit,-1));$bytes=(int)$limit*match($unit){'g'=>1073741824,'m'=>1048576,'k'=>1024,default=>1};if(memory_get_usage(true)+$w*$h*7+32*1048576>$bytes)throw new RuntimeException('This image exceeds the server image-memory limit. Use a smaller image or increase PHP memory_limit.');}
 $src=match($mime){'image/jpeg'=>@imagecreatefromjpeg($path),'image/png'=>@imagecreatefrompng($path),'image/webp'=>@imagecreatefromwebp($path)};if(!$src)throw new RuntimeException('The image could not be decoded.');
 try{if($mime==='image/jpeg'&&function_exists('exif_read_data')){$exif=@exif_read_data($path);$o=(int)($exif['Orientation']??1);if(in_array($o,[2,5,7]))imageflip($src,IMG_FLIP_HORIZONTAL);if($o===4)imageflip($src,IMG_FLIP_VERTICAL);$angle=match($o){3=>180,5,8=>90,6,7=>-90,default=>0};if($angle){$rotated=imagerotate($src,$angle,0);if($rotated){imagedestroy($src);$src=$rotated;}}}$w=imagesx($src);$h=imagesy($src);$dir=$root.'/public/assets/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$stem=$key??bin2hex(random_bytes(16));$product=$purpose==='product';$width=$product?1200:max(1,(int)round($w*min(1,2400/max($w,$h))));$height=$product?1500:max(1,(int)round($h*min(1,2400/max($w,$h))));$dest=imagecreatetruecolor($width,$height);if($product){imagefill($dest,0,0,imagecolorallocate($dest,246,244,238));}else{imagealphablending($dest,false);imagesavealpha($dest,true);imagefill($dest,0,0,imagecolorallocatealpha($dest,0,0,0,127));}$scale=min($width/$w,$height/$h,1);$dw=max(1,(int)round($w*$scale));$dh=max(1,(int)round($h*$scale));imagecopyresampled($dest,$src,(int)(($width-$dw)/2),(int)(($height-$dh)/2),0,0,$dw,$dh,$w,$h);$name=$stem.($product?'-product':'-media').'.webp';$tmp=$dir.'/'.$name.'.tmp-'.bin2hex(random_bytes(5));if(!imagewebp($dest,$tmp,86)||!rename($tmp,$dir.'/'.$name)){@unlink($tmp);throw new RuntimeException('The optimized image could not be saved.');}
 $thumbnail=null;if($product){$th=imagecreatetruecolor(480,600);imagecopyresampled($th,$dest,0,0,0,0,480,600,$width,$height);$tn=$stem.'-thumb.webp';$tt=$dir.'/'.$tn.'.tmp-'.bin2hex(random_bytes(5));if(!imagewebp($th,$tt,82)||!rename($tt,$dir.'/'.$tn)){@unlink($tt);@unlink($dir.'/'.$name);throw new RuntimeException('The product thumbnail could not be saved.');}imagedestroy($th);$thumbnail='/assets/uploads/'.$tn;}imagedestroy($dest);return ['url'=>'/assets/uploads/'.$name,'thumbnail'=>$thumbnail,'width'=>$width,'height'=>$height,'bytes'=>filesize($dir.'/'.$name),'original_width'=>$w,'original_height'=>$h,'purpose'=>$purpose,'format'=>'webp'];}finally{imagedestroy($src);}
}
function normalize_product_image(string $url):string{global $root;$url=media_path($url,false);if(str_ends_with($url,'-product.webp')&&product_thumbnail($url)!==$url)return $url;$key='p-'.substr(hash_file('sha256',$root.'/public'.$url),0,28);$converted='/assets/uploads/'.$key.'-product.webp';if(is_file($root.'/public'.$converted)&&is_file($root.'/public/assets/uploads/'.$key.'-thumb.webp'))return $converted;return optimize_image($root.'/public'.$url,'product',$key)['url'];}
